        g("weekly-review", "Je week rustig afsluiten", "Kijk terug op wat lukte en maak een kleine start voor volgende week.", "Leren & maken", 10, listOf("week", "reflectie", "plannen"),
            s("Noteer wat gelukt is", "Schrijf een paar dingen op die je gedaan of geleerd hebt."),
            s("Kijk wat nog openstaat", "Verplaats onafgemaakte taken bewust in plaats van ze te vergeten."),
            s("Kies één verbetering", "Bedenk wat volgende week gemakkelijker kan maken."),
            s("Bepaal je eerste stap", "Kies één kleine actie waarmee je de volgende week wilt beginnen."))
    )

    fun search(query: String, category: String = "Alles"): List<Guide> {
        val q = query.trim().lowercase()
        return guides.filter { guide ->
            val categoryMatches = category == "Alles" || guide.category == category
            val queryMatches = q.isBlank() || listOf(guide.title, guide.summary, guide.category, guide.tags.joinToString(" "))
                .any { it.lowercase().contains(q) }
            categoryMatches && queryMatches
        }
    }

    private fun s(title: String, instruction: String, tip: String? = null) = GuideStep(title, instruction, tip)

    private fun g(
        id: String,
        title: String,
        summary: String,
        category: String,
        minutes: Int,
        tags: List<String>,
        vararg content: Any
    ): Guide {
        val safetyNote = content.firstOrNull() as? String
        val steps = content.filterIsInstance<GuideStep>()
        return Guide(id, title, summary, category, minutes, tags, steps, safetyNote)
    }
}
